export const clamp=(v,a,b)=>Math.min(b,Math.max(a,v));
export const round=(v,n=3)=>Number(v.toFixed(n));
export const dimsOf=(item,catalog)=>item.dims||catalog.find(c=>c.type===item.type).dims;
export function corners(item,catalog){const [w,d]=dimsOf(item,catalog),r=(item.rot||0)*Math.PI/180,c=Math.cos(r),s=Math.sin(r);return [[-w/2,-d/2],[w/2,-d/2],[w/2,d/2],[-w/2,d/2]].map(([x,z])=>({x:item.x+x*c+z*s,z:item.z-x*s+z*c}));}
export function bounds(item,catalog){const p=corners(item,catalog);return {minX:Math.min(...p.map(p=>p.x)),maxX:Math.max(...p.map(p=>p.x)),minZ:Math.min(...p.map(p=>p.z)),maxZ:Math.max(...p.map(p=>p.z))};}
export function groupBounds(items,catalog){const a=items.map(i=>bounds(i,catalog));return {minX:Math.min(...a.map(i=>i.minX)),maxX:Math.max(...a.map(i=>i.maxX)),minZ:Math.min(...a.map(i=>i.minZ)),maxZ:Math.max(...a.map(i=>i.maxZ))};}
export function overlaps(a,b,catalog,gap=.012){const pa=corners(a,catalog),pb=corners(b,catalog),axes=[];for(const p of [pa,pb])for(let i=0;i<2;i++){const q=p[(i+1)%4],r=p[i],l=Math.hypot(q.x-r.x,q.z-r.z);axes.push({x:-(q.z-r.z)/l,z:(q.x-r.x)/l});}return axes.every(axis=>{const ax=pa.map(p=>p.x*axis.x+p.z*axis.z),bx=pb.map(p=>p.x*axis.x+p.z*axis.z);return Math.min(Math.max(...ax),Math.max(...bx))-Math.max(Math.min(...ax),Math.min(...bx))>gap;});}
export function contain(item,room,catalog){const b=bounds(item,catalog);item.x+=b.minX<0?-b.minX:b.maxX>room.w?room.w-b.maxX:0;item.z+=b.minZ<0?-b.minZ:b.maxZ>room.d?room.d-b.maxZ:0;item.x=round(item.x);item.z=round(item.z);return item;}
export function snapPosition(moving,others,room,catalog,{step=.05,smart=true,threshold=.08}={}){let x=moving.x,z=moving.z;if(step){x=Math.round(x/step)*step;z=Math.round(z/step)*step;}const probe={...moving,x,z},b=bounds(probe,catalog),bx=[b.minX,(b.minX+b.maxX)/2,b.maxX],bz=[b.minZ,(b.minZ+b.maxZ)/2,b.maxZ],guides=[];
 if(smart){const tx=[{value:0,ref:null},{value:room.w/2,ref:null},{value:room.w,ref:null}],tz=[{value:0,ref:null},{value:room.d/2,ref:null},{value:room.d,ref:null}];for(const o of others){const r=bounds(o,catalog);tx.push(...[r.minX,(r.minX+r.maxX)/2,r.maxX].map(value=>({value,ref:o})));tz.push(...[r.minZ,(r.minZ+r.maxZ)/2,r.maxZ].map(value=>({value,ref:o})));}
  for(const [axis,points,targets] of [['x',bx,tx],['z',bz,tz]]){let best=null;for(const p of points)for(const t of targets){const diff=t.value-p;if(Math.abs(diff)<threshold&&(!best||Math.abs(diff)<Math.abs(best.diff)))best={diff,...t};}if(best){if(axis==='x')x+=best.diff;else z+=best.diff;guides.push({axis,value:best.value,ref:best.ref});}}
 }
 const p=contain({...moving,x,z},room,catalog);return {x:p.x,z:p.z,guides:guides.filter(g=>Math.abs((g.axis==='x'?p.x-x:p.z-z))<.001)};
}
export function align(items,mode,catalog){if(items.length<2)return;const b=groupBounds(items,catalog);for(const i of items){const r=bounds(i,catalog);if(mode==='left')i.x+=b.minX-r.minX;if(mode==='centerX')i.x+=(b.minX+b.maxX-r.minX-r.maxX)/2;if(mode==='right')i.x+=b.maxX-r.maxX;if(mode==='top')i.z+=b.minZ-r.minZ;if(mode==='centerZ')i.z+=(b.minZ+b.maxZ-r.minZ-r.maxZ)/2;if(mode==='bottom')i.z+=b.maxZ-r.maxZ;i.x=round(i.x);i.z=round(i.z);}}
export function distribute(items,axis,catalog){if(items.length<3)return;const a=[...items].sort((a,b)=>a[axis]-b[axis]),min=axis==='x'?'minX':'minZ',max=axis==='x'?'maxX':'maxZ',bb=a.map(i=>bounds(i,catalog)),total=bb.reduce((s,b)=>s+b[max]-b[min],0),gap=(bb.at(-1)[max]-bb[0][min]-total)/(a.length-1);let p=bb[0][min];for(let k=0;k<a.length;k++){a[k][axis]=round(a[k][axis]+p-bb[k][min]);p+=bb[k][max]-bb[k][min]+gap;}return gap;}

function pointOnSegment(p,a,b){const dx=b.x-a.x,dz=b.z-a.z,t=clamp(((p.x-a.x)*dx+(p.z-a.z)*dz)/(dx*dx+dz*dz||1),0,1);return{x:a.x+t*dx,z:a.z+t*dz};}
function segmentIntersection(a,b,c,d){const rx=b.x-a.x,rz=b.z-a.z,sx=d.x-c.x,sz=d.z-c.z,den=rx*sz-rz*sx;if(Math.abs(den)<1e-10)return null;const t=((c.x-a.x)*sz-(c.z-a.z)*sx)/den,u=((c.x-a.x)*rz-(c.z-a.z)*rx)/den;return t>=-1e-9&&t<=1+1e-9&&u>=-1e-9&&u<=1+1e-9?{x:a.x+t*rx,z:a.z+t*rz}:null;}
export function objectGap(a,b,catalog){const pa=corners(a,catalog),pb=corners(b,catalog);let best={distance:Infinity,a:pa[0],b:pb[0]};for(let i=0;i<4;i++)for(let j=0;j<4;j++){const a1=pa[i],a2=pa[(i+1)%4],b1=pb[j],b2=pb[(j+1)%4],cross=segmentIntersection(a1,a2,b1,b2);if(cross)return{distance:0,a:cross,b:cross};for(const [p,q,isA] of [[a1,pointOnSegment(a1,b1,b2),true],[a2,pointOnSegment(a2,b1,b2),true],[b1,pointOnSegment(b1,a1,a2),false],[b2,pointOnSegment(b2,a1,a2),false]]){const distance=Math.hypot(p.x-q.x,p.z-q.z);if(distance<best.distance)best={distance,a:isA?p:q,b:isA?q:p};}}
 if(overlaps(a,b,catalog,0))return{distance:0,a:{x:a.x,z:a.z},b:{x:a.x,z:a.z}};return best;
}
export function wallGaps(item,room,catalog){const pts=corners(item,catalog),bb=bounds(item,catalog);const extreme=(axis,value)=>{const p=pts.filter(p=>Math.abs(p[axis]-value)<.00001);return{x:p.reduce((s,p)=>s+p.x,0)/p.length,z:p.reduce((s,p)=>s+p.z,0)/p.length};};return[['left','왼쪽 벽','x',bb.minX,0],['right','오른쪽 벽','x',bb.maxX,room.w],['front','정면 벽','z',bb.minZ,0],['back','후면 벽','z',bb.maxZ,room.d]].map(([key,label,axis,value,target])=>{const a=extreme(axis,value),b={...a,[axis]:target};return{key:`wall:${item.id}:${key}`,kind:'wall',from:item.id,label,a,b,distance:Math.max(0,Math.abs(target-value)),wall:key};});}
export function clearanceMeasurements(items,room,catalog,selectedIds=[]){const selected=new Set(selectedIds),focus=selected.size?items.filter(i=>selected.has(i.id)):items,result=[],seen=new Set(),boxes=new Map(items.map(i=>[i.id,bounds(i,catalog)]));const add=m=>{if(!seen.has(m.key)){seen.add(m.key);result.push(m);}};for(const item of focus){const bb=boxes.get(item.id),candidates=[];for(const other of items){if(other.id===item.id)continue;const bo=boxes.get(other.id);const zOverlap=Math.min(bb.maxZ,bo.maxZ)-Math.max(bb.minZ,bo.minZ),xOverlap=Math.min(bb.maxX,bo.maxX)-Math.max(bb.minX,bo.minX);if(zOverlap>-.001||xOverlap>-.001)candidates.push({other,gap:objectGap(item,other,catalog),xOverlap,zOverlap});}for(const wall of wallGaps(item,room,catalog)){const blocked=candidates.some(({other,zOverlap,xOverlap})=>wall.wall==='left'?zOverlap>0&&other.x<item.x:wall.wall==='right'?zOverlap>0&&other.x>item.x:wall.wall==='front'?xOverlap>0&&other.z<item.z:xOverlap>0&&other.z>item.z);if(selected.size||!blocked)add(wall);}for(const side of ['left','right','front','back']){const near=candidates.filter(c=>side==='left'?c.zOverlap>0&&c.other.x<item.x:side==='right'?c.zOverlap>0&&c.other.x>item.x:side==='front'?c.xOverlap>0&&c.other.z<item.z:c.xOverlap>0&&c.other.z>item.z).sort((a,b)=>a.gap.distance-b.gap.distance)[0];if(!near)continue;const key=[item.id,near.other.id].sort().join(':');add({...near.gap,key,kind:'object',from:item.id,to:near.other.id,label:near.other.name||catalog.find(c=>c.type===near.other.type)?.name||'가구'});}}
 return result;
}
